<script setup>defineProps({steps:{type:Array,default:()=>[]},current:{type:Number,default:0}})</script>
<template><div class="order-progress"><div v-for="(step,i) in steps" :key="step.label" :class="['progress-step',{done:i<=current}]"><div class="progress-mark">{{i<current?'✓':i+1}}</div><div><strong>{{step.label}}</strong><small>{{step.date||step.status}}</small></div></div></div></template>
<style scoped>.order-progress{display:flex;padding:22px 0}.progress-step{position:relative;display:flex;flex:1;gap:10px;align-items:center;color:#8d867e}.progress-step:not(:last-child)::after{content:"";position:absolute;left:38px;right:10px;top:16px;height:1px;background:var(--c-border)}.progress-mark{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#e9e5df;position:relative;z-index:1}.progress-step.done{color:var(--c-primary)}.progress-step.done .progress-mark{background:var(--c-primary);color:#fff}.progress-step strong,.progress-step small{display:block}.progress-step strong{font-size:14px;color:var(--c-text)}.progress-step small{font-size:12px;margin-top:2px}@media(max-width:700px){.order-progress{display:grid;gap:14px}.progress-step:not(:last-child)::after{left:16px;top:32px;bottom:-14px;right:auto;width:1px;height:auto}}</style>
